Ltac brute_regZ0 n r lo cnt g :=
  let w := getreg n in
  lazymatch w with
  | Z_to_bv 64 ?e =>
      let F := eval pattern r in e in
      lazymatch F with
      | ?f r =>
          let H := fresh "BR" in
          assert (H : forall r0, lo <= r0 < lo + cnt -> (f r0 =? g r0) = true)
            by (apply (brute_range (fun r0 => f r0 =? g r0) lo cnt); vm_compute; reflexivity);
          replace e with (g r) by (symmetry; apply Z.eqb_eq; apply H; lia);
          clear H
      end
  | _ => fail "brute_regZ0: register" n "holds" w
  end.

Ltac ztoF pc := repeat (lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).


Ltac afa_popc_tac P r :=
  let p := eval vm_compute in (P + 12) in ztoF p; brute_regZ0 11%Z r 1 255 sm1;
  let p := eval vm_compute in (P + 24) in ztoF p; brute_regZ0 11%Z r 1 255 sm2;
  let p := eval vm_compute in (P + 32) in ztoF p; brute_regZ0 11%Z r 1 255 sm3;
  let p := eval vm_compute in (P + 36) in ztoF p; brute_regZ0 11%Z r 1 255 nsm;
  let p := eval vm_compute in (P + 56) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_a (nsm r0));
  let p := eval vm_compute in (P + 76) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_b (pc_a (nsm r0)));
  let p := eval vm_compute in (P + 84) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_c (pc_b (pc_a (nsm r0))));
  let p := eval vm_compute in (P + 104) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => pc_d (pc_c (pc_b (pc_a (nsm r0)))));
  let p := eval vm_compute in (P + 108) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => 31 - Z.log2 r0);
  let p := eval vm_compute in (P + 112) in ztoF p; brute_regZ0 11%Z r 1 255 (fun r0 => Z.log2 r0);
  let p := eval vm_compute in (P + 120) in ztoF p; brute_regZ0 14%Z r 1 255 (fun r0 => 8 - Z.log2 r0);
  zstep.



Lemma a4_firstn1_skipn : forall (l : list Z) n, (n < length l)%nat -> firstn 1 (skipn n l) = [nth n l 0].
Proof.
  induction l as [|x l IH]; intros n Hn; [cbn in Hn; lia|].
  destruct n as [|n]; [reflexivity|]. cbn [skipn nth]. apply IH. cbn in Hn. lia.
Qed.

Lemma a4_rd1 : forall segs (m : word -> option byte) S (bs : list Z) E j w k,
  bytes_at segs m S (map (Z_to_bv 8) bs) -> Forall (fun c => 0 <= c < 256) bs ->
  ev E j = rdval segs m w 1 false -> w = Z_to_bv 64 (S + k) -> 0 <= k < zlen bs ->
  bv_unsigned (ev E j) = Znth k bs.
Proof.
  intros segs m S bs E j w k HB BY H Hw Hk. subst w. rewrite H. unfold rdval.
  replace (Z_to_bv 64 (S + k)) with (wa (S + Z.of_nat (Z.to_nat k))) by (unfold wa; f_equal; lia).
  rewrite (bytes_at_rdn segs m S _ (Z.to_nat k) 1 HB) by (rewrite length_map; lia).
  rewrite skipn_map, firstn_map, a4_firstn1_skipn by lia.
  assert (R : 0 <= nth (Z.to_nat k) bs 0 < 256).
  { rewrite Forall_forall in BY. apply BY. apply nth_In. lia. }
  unfold Znth. cbn [map extz bytes_le_to_Z]. change (0 ≪ 8) with 0. rewrite Z.lor_0_r.
  rewrite (Z_to_bv_small 8) by (unfold bv_modulus; cbn -[Z.pow]; lia).
  rewrite Z_to_bv_small by (unfold bv_modulus; cbn -[Z.pow]; lia). reflexivity.
Qed.

Lemma a4_byte_rng : forall (bs : list Z) k, Forall (fun c => 0 <= c < 256) bs -> 0 <= k < zlen bs -> 0 <= Znth k bs < 256.
Proof.
  intros bs k BY Hk. unfold Znth. rewrite Forall_forall in BY. apply BY. apply nth_In. lia.
Qed.

Lemma a4_adenot_var : forall E i off z, ev E i = Z_to_bv 64 z -> 0 <= z < 2^64 ->
  adenot E {| a_base := EVar i; a_off := off |} = Z_to_bv 64 (z + off).
Proof.
  intros E i off z H Hz. unfold adenot, PropExec.v_addi. cbn [a_base a_off edenot]. rewrite H, Z_to_bv_small by (unfold bv_modulus; cbn; lia).
  reflexivity.
Qed.

Lemma a4_adenot_ez : forall zv xs a z, 0 <= ez zv (kE zv xs) (a_base a) + a_off a < 2^64 ->
  ez zv (kE zv xs) (a_base a) + a_off a = z -> adenot (kE zv xs) a = wa z.
Proof.
  intros zv xs a z R Hz. apply bv_eq. rewrite adenot_ez by exact R. unfold wa.
  rewrite Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 64) with (2^64).
  rewrite Z.mod_small by lia. exact Hz.
Qed.

Lemma a4_shd_rd : forall segs zv xs (m : word -> option byte) a lo hi x,
  unpoisoned m lo hi -> lo <= x -> x + 1 <= hi ->
  0 <= ez zv (kE zv xs) (a_base a) + a_off a < 2^64 -> ez zv (kE zv xs) (a_base a) + a_off a = shad x ->
  exists bs, rdn segs m (adenot (kE zv xs) a) 1 = Some bs.
Proof.
  intros segs zv xs m a lo hi x U L H R Hz.
  destruct (unp_gran m lo hi x 1 U L ltac:(lia) ltac:(lia)) as (b & Hb & _).
  apply (kx_rd_known_ex segs zv xs m a b (shad x) (shad x + 1)); [| exact R | lia].
  intros s Hs. replace s with (shad x) by lia. exact Hb.
Qed.

Definition a4_ar (P : Prop) : Prop := P.
Definition a4_hide (P : Prop) : Prop := P.
Ltac a4_clr := lazymatch goal with H : a4_ar _ |- _ => clear - H end.
Ltac a4_lia := a4_clr; unfold a4_ar in *; try unfold ASHOFF in *; repeat (match goal with H : _ /\ _ |- _ => destruct H end); Z.div_mod_to_equations; lia.
Ltac a4_zs zv := let na := eval vm_compute in (length zv) in
  cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb].
Ltac a4_fin :=
  try change (2 ^ (3 mod 64)) with 8; try unfold shad, ASHOFF; kx_abstract;
  a4_clr; rewrite ?Z.shiftr_div_pow2 by lia; try change (2 ^ 3) with 8; a4_lia.

Ltac a4_acc :=
  lazymatch goal with
  | |- accP ?RNG ?E (?a, ?n) =>
      let b := eval unfold E in E in
      lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
        change E with (kE zv xs);
        match goal with H : rng RNG ?A ?N |- _ =>
          apply (kx_acc_rng zv xs RNG A N a n H ltac:(repeat constructor)); a4_zs zv; a4_fin end
      end
  end.

Ltac a4_rdb HS :=
  lazymatch goal with
  | |- exists bs, rdn ?segs ?m (adenot ?E {| a_base := EVar ?i; a_off := ?off |}) ?k = Some bs =>
      let b := eval unfold E in E in
      lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
        change E with (kE zv xs);
        apply (kx_rd_ez segs zv xs m {| a_base := EVar i; a_off := off |} k _ _ ltac:(repeat constructor) HS);
        a4_zs zv; rewrite ?length_map; repeat split; a4_fin
      end
  end.

Ltac a4_rds US :=
  lazymatch goal with
  | |- exists bs, rdn ?segs ?m (adenot ?E ?a) 1 = Some bs =>
      lazymatch a with {| a_base := EAlu ALU_SRL ?X (ELit 3); a_off := _ |} =>
        let b := eval unfold E in E in
        lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
          change E with (kE zv xs);
          apply (a4_shd_rd segs zv xs m a _ _ (ez zv (kE zv xs) X) US); a4_zs zv; a4_fin
        end
      end
  end.

Ltac a4_chk US :=
  lazymatch goal with
  | |- branch_taken BC_LT (edenot ?E (EAlu ALU_SUB (EMd M_MUL (EAlu ALU_SLTU (ELit 0) (EVar ?j))
          (EAlu ALU_ADD (EAlu ALU_ADD (EAlu ALU_AND ?B (ELit 7)) (ELit ?k)) (ELit 1))) (ELit 1)))
        (edenot ?E (EVar ?j)) = true =>
      let b := eval unfold E in E in
      lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
        let H := fresh "RV" in kx_read_eq j H;
        lazymatch type of H with _ = rdval ?segs ?m (adenot _ ?a) 1 true =>
          change E with (kE zv xs) in H |- *;
          change (EAlu ALU_SUB (EMd M_MUL (EAlu ALU_SLTU (ELit 0) (EVar j))
                   (EAlu ALU_ADD (EAlu ALU_ADD (EAlu ALU_AND B (ELit 7)) (ELit k)) (ELit 1))) (ELit 1))
            with (chk_ob (EVar j) B k);
          apply (chk_ob_unp segs m (kE zv xs) (EVar j) B k _ _ (ez zv (kE zv xs) B) US
                   (ez_ok zv (kE zv xs) (kE_atoms zv xs) B));
          [ a4_zs zv; a4_fin | a4_zs zv; a4_fin | a4_zs zv; a4_fin | a4_lia
          | cbn [edenot]; rewrite H; f_equal; apply a4_adenot_ez; a4_zs zv; a4_fin ]
        end
      end
  end.

Ltac a4_lbr K S bs HS BY :=
  lazymatch goal with
  | |- branch_taken BC_EQ (edenot ?E (EVar ?j)) (edenot ?E (ELit 0)) = _ =>
      let H := fresh "HR" in kx_read_eq j H;
      lazymatch type of H with
      | ev E j = rdval ?segs ?m (adenot E {| a_base := EVar ?i1; a_off := ?off |}) 1 false =>
        lazymatch goal with KXA : forall j, (j < length ?zv)%nat -> ev E j = _ |- _ =>
          let Z1 := fresh "ZR" in
          assert (Z1 : bv_unsigned (ev E j) = Znth K bs);
          [ apply (a4_rd1 segs m S bs E j _ _ HS BY H);
            [ rewrite (a4_adenot_var E i1 off _ (KXA i1 ltac:(apply Nat.ltb_lt; reflexivity))) by (cbv [nth]; a4_lia);
              cbv [nth]; f_equal; a4_lia
            | a4_lia ]
          | clear H;
            unfold branch_taken; cbn [edenot]; rewrite bv_eqb_Z, Z1; change (bv_unsigned (Z_to_bv 64 0)) with 0;
            first [ apply Z.eqb_neq; assumption | apply Z.eqb_eq; assumption | apply Z.eqb_neq; lia | apply Z.eqb_eq; lia ] ]
        end
      end
  end.

Ltac a4_z :=
  let E := lazymatch goal with
           | |- context [flat ?E _ _] => E | |- context [estart ?E _] => E | |- context [elenZ ?E _] => E end in
  let b := eval unfold E in E in
  lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
    let na := eval vm_compute in (length zv) in
    change E with (kE zv xs); unfold flat;
    repeat match goal with |- _ /\ _ => split end;
    repeat match goal with
    | |- context [estart (kE zv xs) ?a] =>
        rewrite (estart_ez_kE zv xs a); [ | cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; a4_fin ]
    end;
    rewrite ?elenZ_lit by lia;
    cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; a4_fin
  end.

Ltac a4_one HS US :=
  lazymatch goal with
  | |- evtF _ _ _ _ => fail
  | |- region_ok _ _ _ _ => fail
  | |- accP _ _ _ => a4_acc
  | |- exists bs, rdn _ _ (adenot _ {| a_base := EVar _; a_off := _ |}) _ = Some bs => a4_rdb HS
  | |- exists bs, rdn _ _ _ 1 = Some bs => a4_rds US
  | |- branch_taken BC_LT _ _ = true => a4_chk US
  | |- flat _ _ _ => a4_z
  | |- flat _ _ _ /\ _ => a4_z
  | |- branch_taken _ _ _ = _ => w4br
  | |- _ => first [ a4_lia | rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; cbn [cells_size csize]; lia ]
  end.

Section CANSEC1. Context {rc : runConstT}.

Section AFA4.
  Variables (RNG : footprint) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : amem).
  Variables (A DST dcap S DT mtl tt tl mtl' : Z) (src : list Z) (ja : list byte) (lo : Z) (rstk : region).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis HA : rw_cells bsegs m0 A [CB 152 ja].
  Hypothesis A8 : A mod 8 = 0.
  Hypothesis DESC : bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 tt; Z_to_bv 8 tl; Z_to_bv 8 mtl'].
  Hypothesis RM1 : 0 <= mtl < 256.
  Hypothesis RTT : 0 <= tt < 256.
  Hypothesis RTL : 0 <= tl < 256.
  Hypothesis RM2 : 0 <= mtl' < 128.
  Hypothesis SRC : bytes_at bsegs m0 S (map (Z_to_bv 8) src).
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis NSM : n < 2^26.
  Hypothesis S0 : 0 < S.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DE : DST + dcap + 8 <= 2^64.
  Hypothesis DT0 : 0 < DT.
  Hypothesis DTL : DT + 4 <= lo.
  Hypothesis SL : 0 < n -> S + n <= lo.
  Hypothesis STK : stk bsegs m0 lo SP.
  Hypothesis LOS : lo <= SP - AHUF_FAST_ARGS_STACK.
  Hypothesis ASP : SP <= A.
  Hypothesis A47 : A + 152 <= 2^47.
  Hypothesis MI : mem_inv bsegs m0.
  Hypothesis UDT : unpoisoned m0 DT (DT + 4).
  Hypothesis USR : 0 < n -> unpoisoned m0 S (S + n).
  Hypothesis RCL : rclean m0 rstk.
  Hypothesis RLO : r_lo rstk <= A.
  Hypothesis RHI : A + 152 <= r_hi rstk.
  Hypothesis WFR : rng RNG (SP - AHUF_FAST_ARGS_STACK) AHUF_FAST_ARGS_STACK.
  Hypothesis WA : rng RNG A 152.
  Hypothesis WRS : rrng RNG rstk.
  Hypothesis WDT : rng RNG DT 4.
  Hypothesis WDTS : rng RNG (shad DT) 1.
  Hypothesis WSR : 0 < n -> rng RNG S n /\ rng RNG (shad S) (nshad (n + S mod 8)).
  Hypothesis WIM : rng_aimg RNG.
  
  Hypothesis ART : artcells m0.
  Hypothesis LOA : ATOP + 4096 <= lo.
  Hypothesis DT8 : DT mod 8 = 0.

  Notation POST := (fast_args_postA ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A DST dcap S DT src tl lo m0).
  Notation FRS := [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Notation MW := [(SP - AHUF_FAST_ARGS_STACK, SP); (A, A + 152)].


  
  Ltac afa_facts :=
    pose proof (afa_sp0 sp lo A LOA LOS ASP A47) as SPB;
    pose proof (bv_unsigned_in_range 64 sp) as RSP; unfold bv_modulus in RSP; cbn in RSP;
    pose proof (afa_kshz m0 rstk A 152 RCL RLO RHI A8 eq_refl ltac:(lia)) as KSH;
    pose proof ART as (RG0 & RGOT & RGRIC & RMEM & RSHB & _);
    assert (RGOT' : rw_cells bsegs m0 0xaf758 [C8 (Z_to_bv 64 0x1494e8); C8 (Z_to_bv 64 0xb51b8); C8 (Z_to_bv 64 0xb79b8);
                                              C8 (Z_to_bv 64 0xb86a8); C8 (Z_to_bv 64 0xb86b0); C8 (Z_to_bv 64 0xb86a0)]) by exact RGOT;
    assert (RSHB' : rw_cells bsegs m0 0xb79b8 [C8 (Z_to_bv 64 0x7fff8000)]) by exact RSHB;
    clear RG0 RGOT RGRIC RMEM RSHB;
    assert (FAP : KXGoM.apart (SP - 48) 48 0x7fff8000 17592186044416) by (unfold KXGoM.apart; lia);
    assert (AAP : KXGoM.apart A 152 0x7fff8000 17592186044416) by (unfold KXGoM.apart; lia);
    unfold AHUF_FAST_ARGS_STACK in *.

  Ltac a4_crng K S bs HS BY :=
    lazymatch goal with |- 0 <= ?e <= 8 =>
      lazymatch e with context [edenot ?E ?X] =>
        match X with context [EVar ?j] =>
          let H := fresh "HR" in kx_read_eq j H;
          lazymatch type of H with
          | ev E j = rdval ?segs ?m (adenot E ?ad) 1 false =>
            lazymatch goal with KXA : forall j, (j < length ?zv)%nat -> ev E j = _ |- _ =>
              let eb := eval unfold E in E in
              lazymatch eb with kx_env (map (Z_to_bv 64) zv) ?xs =>
              let Z1 := fresh "ZR" in
              assert (Z1 : bv_unsigned (ev E j) = Znth K bs);
              [ apply (a4_rd1 segs m S bs E j _ _ HS BY H);
                [ change E with (kE zv xs); etransitivity;
                  [ apply (a4_adenot_ez zv xs ad (S + K)); a4_zs zv; a4_lia | reflexivity ]
                | a4_lia ]
              | clear H ];
              let RB := fresh "RB" in
              pose proof (a4_byte_rng bs K BY ltac:(a4_lia)) as RB;
              let R1 := fresh "R1" in
              assert (R1 : 1 <= Znth K bs < 1 + 255)
                by first [ lazymatch goal with NZ : Znth K bs <> 0 |- _ => clear - RB NZ; lia end | lia ];
              cbn [edenot];
              replace (ev E j) with (Z_to_bv 64 (Znth K bs)) by (rewrite <- Z1; apply Z_to_bv_bv_unsigned);
              lazymatch goal with |- 0 <= ?e2 <= 8 =>
                let F := eval pattern (Znth K bs) in e2 in
                lazymatch F with ?f _ =>
                  let BR := fresh "BR" in
                  assert (BR : forall r0, 1 <= r0 < 1 + 255 -> ((0 <=? f r0) && (f r0 <=? 8))%bool = true)
                    by (apply (brute_range (fun r0 => ((0 <=? f r0) && (f r0 <=? 8))%bool) 1 255); vm_compute; reflexivity);
                  specialize (BR (Znth K bs) R1); apply andb_prop in BR; destruct BR as [BR1 BR2];
                  apply Z.leb_le in BR1; apply Z.leb_le in BR2; split; [exact BR1 | exact BR2]
                end
              end
              end
            end
          end
        end
      end
    end.

  Ltac a4_c14 HC K S bs HS BY :=
    lazymatch goal with
    | |- evtF _ _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ _ _ _ (Z_to_bv 64 ?c) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
        assert (HC : 0 <= c <= 8) by first [ a4_lia | a4_crng K S bs HS BY | lia ]
    end.

  Ltac a4_log_z zv :=
    let na := eval vm_compute in (length zv) in
    cbn [log_apart_ez log_inside_ez inside cells_size csize]; cbv [ez a_base a_off]; change (length zv) with na;
    cbv [nth Nat.ltb Nat.leb]; rewrite ?length_map;
    first [ solve [a4_lia] | repeat (first [exact I | split]); try first [a4_lia | lia] ].

  Ltac a4_frame H :=
    lazymatch goal with
    | KXLF : log_flat ?E ?log, HK : know_ok ?segs ?E ?m ?kn |- context [MS _ _ _ _ _ (mem_denot ?E ?m ?log) _] =>
      let b := eval unfold E in E in
      lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
        lazymatch type of H with
        | bytes_at _ m ?A ?bs =>
            apply (kx_bytes_at_log segs E m log A bs) in H; [ | exact KXLF | change E with (kE zv xs); apply log_apart_ez_ok; a4_log_z zv ]
        | rw_cells _ m ?A ?cs =>
            apply (kx_rw_cells_log segs E m log A cs) in H; [ | exact KXLF | change E with (kE zv xs); apply log_apart_ez_ok; a4_log_z zv ]
        | munch ?W ?m0 m =>
            apply (kx_munch_log E W m0 m log) in H; [ | exact KXLF | change E with (kE zv xs); apply log_inside_ez_ok; a4_log_z zv ]
        end
      end
    end.

  Ltac a4_estart_z zv :=
    let na := eval vm_compute in (length zv) in
    lazymatch goal with |- estart ?E ?a = ?A =>
      rewrite (estart_ez zv E (kE_atoms zv _) a);
      [ cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; first [a4_lia | lia]
      | cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; first [a4_lia | lia] ]
    end.

  Ltac a4_cell_gen H W :=
    lazymatch goal with
    | HLF : log_flat ?E ?log |- context [MS _ _ _ _ _ (mem_denot ?E ?m ?log) _] =>
      let b := eval unfold E in E in
      lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
        let na := eval vm_compute in (length zv) in
        lazymatch type of H with
        | rw_cells ?segs m ?A [?c0] =>
            let rec go pre l :=
              lazymatch l with
              | SE ?a W ?v :: ?rest =>
                  first [ let Hn := fresh "HC" in
                          assert (Hn : rw_cells segs (mem_denot E m (pre ++ SE a W v :: rest)) A
                                         [ltac:(lazymatch W with 8%nat => exact (C8 (edenot E v)) | _ => exact (C4 (edenot E v)) end)])
                            by (first [ eapply (kx_cell_store8 segs E m pre a v rest A)
                                      | eapply (kx_cell_store4 segs E m pre a v rest A) ];
                                [ change (pre ++ SE a W v :: rest) with log; exact HLF
                                | exact H
                                | change E with (kE zv xs); a4_estart_z zv
                                | change E with (kE zv xs); apply log_apart_ez_ok; a4_log_z zv ]);
                          change (pre ++ SE a W v :: rest) with log in Hn;
                          rewrite (ez_ok zv E (kE_atoms zv xs) v) in Hn;
                          cbv [ez] in Hn; change (length zv) with na in Hn; cbv [nth Nat.ltb Nat.leb] in Hn;
                          rewrite ?Z_to_bv_bv_unsigned in Hn;
                          clear H; rename Hn into H
                        | let pre' := eval cbn [app] in (pre ++ [SE a W v]) in go pre' rest ]
              | ?e :: ?rest => let pre' := eval cbn [app] in (pre ++ [e]) in go pre' rest
              | [] => fail "a4_cell_gen: no store found for" A
              end in
            let l := eval hnf in log in
            go constr:(@nil sentry) l
        end
      end
    end.

  Ltac a4_cells_post :=
    repeat match goal with
    | HLF : log_flat ?E ?log, H : rw_cells ?segs ?m ?A [?c] |- context [MS _ _ _ _ _ (mem_denot ?E ?m ?log) _] =>
        let l := eval hnf in log in
        lazymatch A with
        | _ + ?off => tryif kx_log_has_off l off then first [ a4_cell_gen H 8%nat | a4_cell_gen H 4%nat | a4_frame H ]
                      else a4_frame H
        | _ => first [ a4_cell_gen H 8%nat | a4_cell_gen H 4%nat | a4_frame H ]
        end
    end.

  Ltac a4_merge :=
    repeat (lazymatch goal with |- rw_cells ?segs ?m ?A (?c :: ?c' :: ?cs) =>
              apply (proj2 (kx_rwc_cons segs m A c (c' :: cs))); split; [eassumption|]; cbn [csize];
              lazymatch goal with
              | |- rw_cells _ _ (?a + ?b + Z.of_nat ?k) _ =>
                  tryif is_Zlit b then
                    (let v := eval vm_compute in (b + Z.of_nat k) in
                     replace (a + b + Z.of_nat k) with (a + v) by first [ rewrite <- Z.add_assoc; reflexivity | lia ])
                  else (let v := eval vm_compute in (Z.of_nat k) in change (Z.of_nat k) with v)
              | |- rw_cells _ _ (?a + Z.of_nat ?k) _ =>
                  let v := eval vm_compute in (Z.of_nat k) in change (Z.of_nat k) with v
              end end);
    eassumption.

  Ltac a4_sent Acell SENT :=
    lazymatch goal with H : rw_cells bsegs _ Acell [C8 (edenot ?E (EAlu ALU_SLL (EAlu ALU_ADD ?Y (ELit 1)) (EVar ?j)))],
                        HKn : know_ok bsegs ?E ?mb ?kn, KA : forall j0, (j0 < length ?zv)%nat -> ev ?E j0 = _ |- _ =>
      let al := eval vm_compute in (ealign kn Y) in
      assert (SENT : bv_unsigned (edenot E (EAlu ALU_SLL (EAlu ALU_ADD Y (ELit 1)) (EVar j))) mod 512 <> 0);
      [ change (edenot E (EAlu ALU_SLL (EAlu ALU_ADD Y (ELit 1)) (EVar j)))
          with (alu64 ALU_SLL (alu64 ALU_ADD (edenot E Y) (Z_to_bv 64 1)) (ev E j));
        apply afa_sentinel_add;
        [ let AL := fresh "AL" in let DV := fresh "DV" in
          destruct (ealign_sound bsegs E mb kn Y HKn) as (AL & DV);
          replace (ealign kn Y) with al in DV by (vm_compute; reflexivity);
          apply (afa_even_of_div _ al); [first [a4_lia | lia] | exact DV]
        | rewrite KA by (cbv; first [a4_lia | lia]); cbv [nth];
          rewrite Z_to_bv_unsigned, bv_wrap_small by (unfold bv_modulus; cbn; first [a4_lia | lia]); first [a4_lia | lia] ]
      | ]
