    rewrite Z_to_bv_small by (unfold bv_modulus; cbn -[Z.pow]; rewrite Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia).
    cbn [outside]; rewrite Z.shiftr_div_pow2 by lia; change (2^3) with 8; repeat split; lia. }
  lazymatch type of USRn with ?P _ _ _ => assert (USRm : P mm S (S + n)) end.
  { pose proof USRn as (U0 & U1 & U2). split; [exact U0|]. split; [exact U1|].
    intros G G1 G2 G3. destruct (U2 G G1 G2 G3) as (b & Hb & Hgr). exists b. split; [|exact Hgr].
    rewrite (MUm (wa (ASHOFF + G))); [exact Hb|].
    unfold wa, ASHOFF. rewrite Z_to_bv_small by (unfold bv_modulus; cbn -[Z.pow]; lia). cbn [outside]; repeat split; lia. }
  pose proof afa_was as WAS.
  lazymatch type of WAS with rng _ (?o + Z.shiftr _ 3) _ =>
    assert (WAS2 : rng RNG (o + Z.shiftr A 3) (Z.shiftr (152 + A mod 8 + 7) 3)) by (rewrite A8; exact WAS) end.
  assert (WSRc : rng RNG (shad S) (Z.shiftr (n + S mod 8 + 7) 3)) by exact WSRb.

  assert (KB : 0 <= I3 - 1 - S < n) by lia.
  pose proof (a4_byte_rng src (I3 - 1 - S) BYS KB) as LBR.
  assert (AR : a4_ar (0 < S /\ S + n <= lo /\ lo <= SP - 48 /\ SP <= A /\ A + 152 <= 2^47 /\ n < 2^26 /\
               I0 = S + 6 /\ I1 = I0 + jt_len src 0 /\ I2 = I1 + jt_len src 2 /\ I3 = I2 + jt_len src 4 /\
               8 <= jt_len src 0 /\ 8 <= jt_len src 2 /\ 8 <= jt_len src 4 /\ I3 + 8 <= S + n /\ ASHOFF + 2^44 <= A /\ 0 <= c <= 8)) by (unfold a4_ar, ASHOFF; repeat split; lia).
  let PxS := constr:([AHUF_FAST_ARGS_INIT + 1772] : list Z) in let PxF := constr:(600%nat : nat) in let PxD := eval vm_compute in (repeat false 4096) in let PxK := constr:([KZRange dcap 1 (2^32 - 1); KZRange n 10 (2^26 - 1); KZRange S 1 (2^47); KZRange DST 0 (2^64 - 9); KZRange (DST + dcap) 2 (2^64 - 8); KZRange DT 1 (2^47); KZAlign DT 8; KZRange SP 0x7fff7f801030 (2^47-152); KZRange I0 1 (2^47); KZRange I1 1 (2^47); KZRange I2 1 (2^47); KZRange I3 1 (2^47); KZRange SG 0 (2^30); KZRange c 0 8; KZAlign A 8; KZRange A 1 (2^47); KZWr A 152; KZDisj A 152 S n; KZShZ 2147450880 A 152; KZWord 0xb2128 8 0xba2f8; KZWord 0xba2f8 8 0x7fff8000] : list kz) in let PxR := constr:([(S, n)] : list (Z * Z)) in let PxW := constr:([(SP - 48, 48); (A, 152); (S, n); (0xb2128, 8); (0xba2f8, 8)] : list (Z * Z)) in let PxU := constr:([(S, n)] : list (Z * Z)) in kx_prepFm PxS PxF PxK PxR PxW PxU; kx_goFL PxD.
  all: try a4_lbr (I3 - 1 - S) S src SRCm BYS.
  all: try (lazymatch goal with |- accP _ _ _ => a4_acc end).
  all: try (lazymatch goal with |- exists bs, rdn _ _ (adenot _ {| a_base := EVar _; a_off := _ |}) _ = Some bs => a4_rdb SRCm end).
  all: try (lazymatch goal with |- exists bs, rdn _ _ _ 1 = Some bs => a4_rds USRm end).
  all: try (lazymatch goal with |- branch_taken BC_LT _ _ = true => a4_chk USRm end).
  all: try (lazymatch goal with |- flat _ _ _ => a4_z | |- flat _ _ _ /\ _ => a4_z end).
  all: try a4_one SRCm USRm.
  all: try (lazymatch goal with |- evtF _ _ _ _ => fail | |- ?g => idtac "LEFT" g end).
  unfold a4_hide in *. clear HAm.
  a4_cells_post.
  pose proof SRCm as SRC0.
  a4_frame SRCm.
  a4_frame MUm.
  all: try (lazymatch goal with |- evtF _ _ _ _ => fail | |- _ => (rewrite ?length_map; cbn [cells_size csize]; first [a4_lia | lia]) end).
  kx_post_mem_free.
  kx_post_regs_keep.
  a4_c14 HC (I3 - 1 - S) S src SRC0 BYS. clear SRC0.
  a4_sent (A + 72) SENT.
  try clearbody KXE; try clearbody KXxs.
  eapply (K _ b0 _ w10 w11 w12 w13 w14 I0 I1 I2 I3 SG).
  all: first [ exact TL | exact HC | exact SENT | assumption | (lazymatch goal with |- rw_cells _ _ _ (_ :: _ :: _) => a4_merge end) | a4_lia | lia ].
Qed.

  
  Lemma afa_b1 : AFA_J2 -> AFA_J1.
Proof using All.
